document.addEventListener('input',e=>{if(e.target.id==='wardrobe-search'){wardrobeFilters.search=e.target.value;filterWardrobe();}if(solo&&e.target.id==='solo-answer')solo.typedDraft=e.target.value;});
document.addEventListener('change',async e=>{if(e.target.id==='assignment-crossword-clue'){saveDraft();crosswordEntry=Number(e.target.value);renderPractice();return;}if(e.target.id==='expedition-class'){await loadExpedition(e.target.value);return;}if(e.target.id==='practice-activity'){try{practice=await api('practice-activity',{assignmentId:practice.assignment.id,lease:practice.lease,questionKey:practice.question.key,activity:e.target.value});$('#practice-activity-body').innerHTML=activityMarkup(practice.word.activity,'typed-answer')+(practice.word.activity?.kind==='crossword'?crosswordMarkup(practice.word.crossword):'')+(practice.word.activity?.kind==='chain'?`<p>${practice.word.chain} consecutive correct answers</p>`:'');}catch(error){notice(error.message,true);}return;}if(e.target.id==='wardrobe-slot'){wardrobeSlot=e.target.value;filterWardrobe();}if(e.target.id==='wardrobe-availability'){wardrobeFilters.availability=e.target.value;filterWardrobe();}if(e.target.id==='wardrobe-sort'){wardrobeFilters.sort=e.target.value;filterWardrobe();}if(solo&&e.target.id==='solo-strict-accents')solo.strictAccents=e.target.checked;if(solo&&e.target.id==='solo-category'){try{if(soloBusy)return;await soloSaves;await openSolo(solo.classId,solo.listId,e.target.value);}catch(err){notice(err.message,true);}}});
$('#dialog').addEventListener('close',()=>{music.stop();if(screen==='practice')$('#typed-answer')?.focus({preventScroll:true});});
document.addEventListener('change',async e=>{if(e.target.id==='assignment-crossword-clue'){saveDraft();crosswordEntry=Number(e.target.value);renderPractice();return;}if(e.target.id==='reward-class'){try{rewardsView=await api('study-rewards',{classId:e.target.value});renderHome();}catch(err){notice(err.message,true);}}if(e.target.id==='student-class-code')googleLogin();if(e.target.matches('#host-form select[name=mode]'))music.enter({mode:e.target.value,status:'playing'});});
