setInterval(()=>{if(screen!=='home'||hubView!=='arcade'||tab!=='leagues'||!leagueData)return;const remaining=leagueData.resetAt-leagueData.now-(performance.now()-leagueSyncedAt),timer=$('[data-league-countdown]');if(timer)timer.textContent=leagueTimeLeft(remaining);if(remaining<=0&&!leagueBusy&&!document.hidden&&!document.activeElement?.matches('input,textarea,select')&&!$('#dialog').open&&navigator.onLine&&performance.now()>=leagueNextRetry){leagueNextRetry=performance.now()+15000;leagueTier=undefined;leagueData=null;renderHome();loadLeagues();}},1000);
setInterval(async()=>{if(screen!=='home'||!home||hubView==='expeditions'||document.activeElement?.matches('input,textarea,select')||$('#dialog').open||tab==='raffle'||tab==='rewards'&&home.user.role==='teacher'||document.hidden||polling)return;polling=true;try{home=await api('home');if(tab==='leagues'){await loadLeagues();return;}const y=scrollY;renderHome();scrollTo(0,y);}catch{}finally{polling=false;}},15000);
if(new URLSearchParams(location.search).has('join'))location.replace('/play.html'+location.search);else (async()=>{if(pendingClassCode){const invite=await api('class-invite',{code:pendingClassCode});inviteName=invite.name;}await refresh();})().catch(e=>{frame(`<section class="panel"><h1>Could not load your classroom.</h1><p style="margin:15px 0">${esc(e.message)}</p><button class="btn primary" onclick="location.reload()">Retry</button></section>`);});
